on conflict (tournament_id) do update set field = excluded.field, updated_at = now();

-- VERIFY (read-only): 56 players, the same keys as an earlier event, prices = player_stats
select jsonb_array_length(field) as players,
       (select string_agg(k, ',' order by k) from jsonb_object_keys(field->0) k) as keys
  from public.tournament_fields where tournament_id = 'paris_2026';
select count(*) as price_or_tier_mismatches
  from public.tournament_fields f, jsonb_array_elements(f.field) p
  join public.player_stats s on s.tournament_id = 'paris_2026' and s.id = p->>'id'
 where f.tournament_id = 'paris_2026' and ((p->>'price')::numeric <> s.price or lower(s.tier) <> p->>'tier');   -- expect 0

